#!/usr/bin/env node
/**
 * Deploy-time database migrator (node-postgres, `pg`).
 *
 * Runs during `npm run build` — on every Vercel deploy — applying pending files
 * in ../migrations to DATABASE_URL. Each file is applied in one transaction and
 * recorded in a `_migrations` table, so it runs once and is safe to re-run.
 *
 * No DATABASE_URL (local / preview builds) -> skip; the PGLite fallback applies
 * the same files at startup instead (see src/lib/db.ts).
 */
import { readdir, readFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";
import pg from "pg";

const databaseUrl = process.env.DATABASE_URL;
if (!databaseUrl) {
  console.log(
    "[migrate] DATABASE_URL not set — skipping (the PGLite fallback migrates itself).",
  );
  process.exit(0);
}

const migrationsDir = join(dirname(fileURLToPath(import.meta.url)), "..", "migrations");

async function main() {
  const pool = new pg.Pool({ connectionString: databaseUrl, max: 1 });
  const client = await pool.connect();
  try {
    await client.query(
      "CREATE TABLE IF NOT EXISTS _migrations (name TEXT PRIMARY KEY, applied_at TIMESTAMPTZ NOT NULL DEFAULT now())",
    );
    const applied = new Set(
      (await client.query("SELECT name FROM _migrations")).rows.map((r) => r.name),
    );

    let files;
    try {
      files = (await readdir(migrationsDir)).filter((f) => f.endsWith(".sql")).sort();
    } catch {
      console.log("[migrate] no migrations/ directory — nothing to do.");
      return;
    }

    let count = 0;
    for (const name of files) {
      if (applied.has(name)) continue;
      const text = await readFile(join(migrationsDir, name), "utf8");
      try {
        await client.query("BEGIN");
        // pg's simple-query protocol runs a whole multi-statement file at once.
        await client.query(text);
        await client.query("INSERT INTO _migrations (name) VALUES ($1)", [name]);
        await client.query("COMMIT");
      } catch (err) {
        console.error(`[migrate] error applying ${name}`);
        try {
          await client.query("ROLLBACK");
        } catch {
          // ROLLBACK fails when the connection died — keep the original error.
        }
        throw err;
      }
      console.log(`[migrate] applied ${name}`);
      count += 1;
    }
    console.log(count ? `[migrate] done — ${count} migration(s) applied.` : "[migrate] up to date.");
  } finally {
    client.release();
    await pool.end();
  }
}

main().catch((err) => {
  console.error("[migrate] failed:", err?.message || err);
  // pg errors carry the context needed to debug a bad SQL file.
  for (const key of ["code", "detail", "hint", "position", "where"]) {
    if (err?.[key] != null) console.error(`[migrate]   ${key}: ${err[key]}`);
  }
  process.exit(1);
});

import { Link } from "@tanstack/react-router";
import { ArrowRight } from "lucide-react";
import { Button } from "./ui/button";

type Props = {
  title?: string;
  description?: string;
  image?: string;
};

export function CtaBand({
  title = "Ready to Level Up?",
  description = "Premium tile design and installation for Greenville and the Upstate. Book a consultation and let's elevate every surface.",
  image = "https://cdn.jsdelivr.net/gh/johnmatveyev-lab/level-up-tile@main/public/images/cta-hex.jpg",
}: Props) {
  return (
    <section className="relative overflow-hidden">
      <img
        src={image}
        alt=""
        className="absolute inset-0 h-full w-full object-cover"
      />
      <div className="absolute inset-0 bg-forest-deep/80" />
      <div className="relative mx-auto flex max-w-7xl flex-col items-start gap-6 px-5 py-20 md:px-8 md:py-28 lg:flex-row lg:items-center lg:justify-between">
        <div className="max-w-xl">
          <p className="mb-3 text-xs font-medium tracking-[0.22em] uppercase text-gold">
            Next Step
          </p>
          <h2 className="font-display text-4xl text-cream md:text-5xl">
            {title}
          </h2>
          <p className="mt-4 text-base text-cream/75 md:text-lg">
            {description}
          </p>
        </div>
        <Button asChild size="xl" variant="gold">
          <Link to="/contact">
            Book Consultation
            <ArrowRight className="h-4 w-4" />
          </Link>
        </Button>
      </div>
    </section>
  );
}

import { useState, useEffect } from "react";
import { Link, useRouterState } from "@tanstack/react-router";
import { Menu, X, ArrowUpRight } from "lucide-react";
import { Logo } from "./Logo";
import { Button } from "./ui/button";
import { nav } from "@/lib/data";
import { cn } from "@/lib/utils";

export function Header() {
  const [open, setOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);
  const pathname = useRouterState({ select: (s) => s.location.pathname });

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 12);
    onScroll();
    window.addEventListener("scroll", onScroll, { passive: true });
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  useEffect(() => {
    setOpen(false);
  }, [pathname]);

  useEffect(() => {
    document.body.style.overflow = open ? "hidden" : "";
    return () => {
      document.body.style.overflow = "";
    };
  }, [open]);

  return (
    <header
      className={cn(
        "fixed inset-x-0 top-0 z-50 transition-all duration-300",
        scrolled || open
          ? "bg-ivory/95 backdrop-blur-md shadow-soft border-b border-border"
          : "bg-ivory/90 backdrop-blur-sm",
      )}
    >
      <div className="mx-auto flex h-16 max-w-7xl items-center justify-between gap-4 px-5 md:h-[4.5rem] md:px-8">
        <Logo size="sm" />

        <nav className="hidden items-center gap-0.5 lg:flex" aria-label="Primary">
          {nav.map((item) => {
            const active =
              pathname === item.href ||
              (item.href !== "/" && pathname.startsWith(item.href));
            return (
              <Link
                key={item.href}
                to={item.href}
                className={cn(
                  "px-3.5 py-2 text-[0.78rem] font-medium tracking-[0.12em] uppercase transition-colors",
                  active
                    ? "text-forest border-b-2 border-gold"
                    : "text-ink-muted hover:text-forest",
                )}
              >
                {item.label}
              </Link>
            );
          })}
        </nav>

        <div className="hidden lg:block">
          <Button asChild size="sm" variant="forest">
            <Link to="/contact">
              Start Your Project
              <ArrowUpRight className="h-3.5 w-3.5" />
            </Link>
          </Button>
        </div>

        <button
          type="button"
          className="flex h-11 w-11 items-center justify-center rounded-md text-forest lg:hidden"
          onClick={() => setOpen((v) => !v)}
          aria-expanded={open}
          aria-label={open ? "Close menu" : "Open menu"}
        >
          {open ? <X className="h-5 w-5" /> : <Menu className="h-5 w-5" />}
        </button>
      </div>

      <div
        className={cn(
          "fixed inset-x-0 top-16 bottom-0 z-40 bg-ivory transition-transform duration-300 md:top-[4.5rem] lg:hidden",
          open ? "translate-x-0" : "translate-x-full pointer-events-none",
        )}
        aria-hidden={!open}
      >
        <nav className="flex h-full flex-col px-6 py-8" aria-label="Mobile">
          <div className="flex flex-col gap-1">
            {nav.map((item) => (
              <Link
                key={item.href}
                to={item.href}
                className="border-b border-border py-4 font-display text-3xl text-forest"
              >
                {item.label}
              </Link>
            ))}
          </div>
          <div className="mt-auto pb-8">
            <Button asChild size="lg" className="w-full" variant="gold">
              <Link to="/contact">Book a Consultation</Link>
            </Button>
          </div>
        </nav>
      </div>
    </header>
  );
}

import { Header } from "./Header";
import { Footer } from "./Footer";

export function Layout({ children }: { children: React.ReactNode }) {
  return (
    <div className="flex min-h-dvh flex-col">
      <Header />
      <main className="flex-1 pt-[4.5rem]">{children}</main>
      <Footer />
    </div>
  );
}

import { Link } from "@tanstack/react-router";
import { cn } from "@/lib/utils";

type LogoProps = {
  className?: string;
  theme?: "light" | "dark";
  size?: "sm" | "md";
};

export function Logo({ className, theme = "dark", size = "md" }: LogoProps) {
  const ink = theme === "dark" ? "text-forest" : "text-cream";
  const gold = theme === "dark" ? "text-gold-dark" : "text-gold";
  const sub = theme === "dark" ? "text-stone" : "text-gold-light/80";

  return (
    <Link
      to="/"
      className={cn("group flex items-center gap-3 no-underline", className)}
      aria-label="Level Up Tile home"
    >
      <span
        className={cn(
          "relative flex shrink-0 items-center justify-center rounded-sm border border-current",
          gold,
          size === "sm" ? "h-9 w-9" : "h-11 w-11",
        )}
        aria-hidden
      >
        {/* Geometric LU monogram */}
        <svg
          viewBox="0 0 40 40"
          className={cn(size === "sm" ? "h-6 w-6" : "h-7 w-7")}
          fill="currentColor"
        >
          <path d="M8 8h5.2v17.2H22V30H8V8z" />
          <path d="M24 8h5.2v22H24V8z" opacity="0.85" />
          <path
            d="M8 8h18.2v3.2H13.2v14H22V28.4H8V8z"
            fill="none"
          />
        </svg>
      </span>
      <div className="flex flex-col leading-none">
        <span
          className={cn(
            "font-display tracking-[0.14em] uppercase",
            size === "sm" ? "text-[1.05rem]" : "text-lg",
            ink,
          )}
        >
          Level Up Tile
        </span>
        <span
          className={cn(
            "mt-1 font-body tracking-[0.28em] uppercase",
            size === "sm" ? "text-[0.55rem]" : "text-[0.6rem]",
            sub,
          )}
        >
          Luxury Tile & Stone
        </span>
      </div>
    </Link>
  );
}

